// Unit-price suggestions by similarity search over reference items: seed orientation values
// plus the company's own priced LVs (history). Numbers are computed, never generated by an LLM.
import type { LVDocument, LVItem, PriceSuggestion } from './types.ts';
import { tokens, quantile } from './text.ts';
import { normUnit } from './units.ts';
import { SEED_PRICES } from './refprices.ts';

export interface RefItem {
  text: string;
  unit: string | null; // normalized
  up: number;
  low?: number;
  high?: number;
  project: string;
  year: number;
  toks?: string[];
}

// Rough construction price index (Baupreisindex-like), used to bring history to today's level.
const INDEX: Record<number, number> = { 2018: 0.68, 2019: 0.71, 2020: 0.73, 2021: 0.8, 2022: 0.92, 2023: 0.97, 2024: 0.99, 2025: 1.0, 2026: 1.03 };
const NOW = 2026;
const idx = (y: number) => INDEX[y] ?? (y < 2018 ? 0.65 : INDEX[NOW]);

export class PriceBook {
  refs: RefItem[] = [];
  private df = new Map<string, number>();
  private dirty = true;

  constructor(withSeed = true) {
    if (withSeed)
      for (const s of SEED_PRICES)
        this.refs.push({ text: s.text, unit: normUnit(s.unit) || s.unit, up: s.mid, low: s.low, high: s.high, project: 'Orientierungswert', year: 2025 });
  }

  learn(doc: LVDocument, year = NOW): number {
    let n = 0;
    const label = doc.project.label || doc.project.name || doc.fileName;
    for (const it of doc.items) {
      if (it.up == null || it.up <= 0 || !it.shortText) continue;
      if (it.flags.bedarf || it.flags.wahl) continue;
      this.refs.push({ text: it.shortText + ' ' + it.longText.slice(0, 200), unit: it.unitNorm, up: it.up, project: label, year });
      n++;
    }
    this.dirty = true;
    return n;
  }

  private prepare() {
    if (!this.dirty) return;
    this.df.clear();
    for (const r of this.refs) {
      r.toks = [...new Set(tokens(r.text))];
      for (const t of r.toks) this.df.set(t, (this.df.get(t) || 0) + 1);
    }
    this.dirty = false;
  }
  private idf(t: string): number {
    return Math.log(1 + this.refs.length / (1 + (this.df.get(t) || 0)));
  }

  suggest(item: LVItem, excludeProject?: string): PriceSuggestion | null {
    this.prepare();
    if (!item.unitNorm || !item.shortText) return null;
    const q = [...new Set(tokens(item.shortText + ' ' + item.longText.slice(0, 160)))];
    const qShort = new Set(tokens(item.shortText));
    if (!q.length) return null;
    let qn = 0;
    for (const t of q) qn += this.idf(t) ** 2 * (qShort.has(t) ? 4 : 1);
    const scored: { r: RefItem; sim: number }[] = [];
    for (const r of this.refs) {
      if (r.unit !== item.unitNorm) continue;
      if (excludeProject && r.project === excludeProject) continue;
      const rs = new Set(r.toks);
      let dot = 0;
      let rn = 0;
      for (const t of r.toks!) rn += this.idf(t) ** 2;
      for (const t of q) if (rs.has(t)) dot += this.idf(t) ** 2 * (qShort.has(t) ? 2 : 1);
      // partial credit for compound words (Zementestrich ~ estrich)
      for (const t of qShort) {
        if (rs.has(t) || t.length < 6) continue;
        for (const u of r.toks!) if (u.length >= 5 && u !== t && (t.includes(u) || u.includes(t))) { dot += 0.5 * this.idf(u) ** 2; break; }
      }
      const sim = dot / Math.sqrt(qn * rn || 1);
      if (sim >= 0.3) scored.push({ r, sim });
    }
    if (!scored.length) return null;
    scored.sort((a, b) => b.sim - a.sim);
    const top = scored.filter((s) => s.sim >= scored[0].sim * 0.75).slice(0, 8);
    const adj = (r: RefItem, v: number) => (v * idx(NOW)) / idx(r.year);
    const pts: number[] = [];
    for (const { r } of top) {
      pts.push(adj(r, r.up));
      if (r.low != null) pts.push(adj(r, r.low));
      if (r.high != null) pts.push(adj(r, r.high));
    }
    const own = top.filter((t) => t.r.project !== 'Orientierungswert').length;
    const single = pts.length === 1;
    const mid = quantile(pts, 0.5);
    const low = single ? mid * 0.8 : quantile(pts, 0.15);
    const high = single ? mid * 1.25 : quantile(pts, 0.85);
    const confidence = Math.min(0.95, top[0].sim * 0.8 + Math.min(own, 4) * 0.06);
    return {
      itemId: item.id,
      low,
      mid,
      high,
      n: top.length,
      confidence,
      refs: top.slice(0, 4).map(({ r, sim }) => ({ text: r.text.slice(0, 90), unit: r.unit || '', up: adj(r, r.up), project: r.project, year: r.year, sim })),
    };
  }
}
